import subprocess
import sys


def run_wc(*args):
    return subprocess.run([sys.executable, "wc.py", *args], capture_output=True, text=True)


def test_text_output_is_unchanged():
    out = run_wc("sample.txt")
    assert out.returncode == 0
    assert out.stdout.splitlines()[:4] == ["lines: 4", "words: 12", "unique: 8", "the 3"]


def test_default_top_is_five_lines():
    out = run_wc("sample.txt")
    assert out.stdout.splitlines()[4:] == ["the 3", "cat 2", "sat 2", "ran 1", "a 1"]


def test_top_n_text():
    out = run_wc("sample.txt", "--top", "2")
    assert out.returncode == 0
    assert out.stdout.splitlines() == ["lines: 4", "words: 12", "unique: 8", "the 3", "cat 2"]


def test_top_n_before_file_and_equals_form():
    assert run_wc("--top", "3", "sample.txt").stdout == run_wc("sample.txt", "--top", "3").stdout
    assert run_wc("sample.txt", "--top=2").stdout == run_wc("sample.txt", "--top", "2").stdout


def test_top_n_json():
    out = run_wc("sample.txt", "--top", "3", "--json")
    assert out.returncode == 0
    data = json.loads(out.stdout)
    assert data == {"lines": 4, "words": 12, "unique": 8, "top": [["the", 3], ["cat", 2], ["sat", 2]]}


def test_json_default_top_is_five():
    out = run_wc("sample.txt", "--json")
    assert out.returncode == 0
    data = json.loads(out.stdout)
    assert data["top"] == [["the", 3], ["cat", 2], ["sat", 2], ["ran", 1], ["a", 1]]


def test_options_after_file_name():
    out = run_wc("sample.txt", "--json")
    assert out.returncode == 0
    json.loads(out.stdout)


def test_ties_keep_first_seen_order():
    out = run_wc("sample.txt", "--top", "4")
    lines = out.stdout.splitlines()
    assert lines[4:] == ["the 3", "cat 2", "sat 2", "ran 1"]


def test_missing_file_error():
    out = run_wc("no_such_file_xyz.txt")
    assert out.returncode == 2
    assert out.stderr.strip() == "error: no such file: no_such_file_xyz.txt"
    assert out.stdout == ""


def test_missing_file_with_options():
